Based on the commit message, the root cause and the patch provided below, you need to:

1. explain how the bug occurs, including all code statements that are most likely to lead to the bug and why. 
2. explain how the bug is fixed, including code statements fixing the bug and why. 

You must include one or more code statements in point 1 and 2.
Code statements included in point 1 should be as brief as possible, only include the ones that are most related to the root cause and  the number of code statements may not exceed 3.


Here is the commit message:
spi: tegra210-quad: Protect curr_xfer check in IRQ handler

Now that all other accesses to curr_xfer are done under the lock,
protect the curr_xfer NULL check in tegra_qspi_isr_thread() with the
spinlock. Without this protection, the following race can occur:

  CPU0 (ISR thread)              CPU1 (timeout path)
  ----------------               -------------------
  if (!tqspi->curr_xfer)
    // sees non-NULL
                                 spin_lock()
                                 tqspi->curr_xfer = NULL
                                 spin_unlock()
  handle_*_xfer()
    spin_lock()
    t = tqspi->curr_xfer  // NULL!
    ... t->len ...        // NULL dereference!

With this patch, all curr_xfer accesses are now properly synchronized.

Although all accesses to curr_xfer are done under the lock, in
tegra_qspi_isr_thread() it checks for NULL, releases the lock and
reacquires it later in handle_cpu_based_xfer()/handle_dma_based_xfer().
There is a potential for an update in between, which could cause a NULL
pointer dereference.

To handle this, add a NULL check inside the handlers after acquiring
the lock. This ensures that if the timeout path has already cleared
curr_xfer, the handler will safely return without dereferencing the
NULL pointer.

Fixes: b4e002d8a7ce ("spi: tegra210-quad: Fix timeout handling")
Signed-off-by: Breno Leitao <leitao@debian.org>
Tested-by: Jon Hunter <jonathanh@nvidia.com>
Acked-by: Jon Hunter <jonathanh@nvidia.com>
Acked-by: Thierry Reding <treding@nvidia.com>
Link: https://patch.msgid.link/20260126-tegra_xfer-v2-6-6d2115e4f387@debian.org
Signed-off-by: Mark Brown <broonie@kernel.org>

Here is the root cause:
Race condition between the interrupt handler thread (tegra_qspi_isr_thread) and the timeout path where the timeout path can set curr_xfer to NULL without proper locking, causing the interrupt handler to dereference a NULL pointer when it later accesses curr_xfer.

Here is the patch:

 static irqreturn_t handle_cpu_based_xfer(struct tegra_qspi *tqspi)
 {
 	struct spi_transfer *t;
 	unsigned long flags;

 	spin_lock_irqsave(&tqspi->lock, flags);
 	t = tqspi->curr_xfer;

+	if (!t) {
+		spin_unlock_irqrestore(&tqspi->lock, flags);
+		return IRQ_HANDLED;
+	}
+
 	if (tqspi->tx_status ||  tqspi->rx_status) {
 		tegra_qspi_handle_error(tqspi);
 		complete(&tqspi->xfer_completion);
 		goto exit;
 	}

 	if (tqspi->cur_direction & DATA_DIR_RX)
 		tegra_qspi_read_rx_fifo_to_client_rxbuf(tqspi, t);

 	if (tqspi->cur_direction & DATA_DIR_TX)
 		tqspi->cur_pos = tqspi->cur_tx_pos;
 	else
 		tqspi->cur_pos = tqspi->cur_rx_pos;

 	if (tqspi->cur_pos == t->len) {
 		complete(&tqspi->xfer_completion);
 		goto exit;
 	}

 	tegra_qspi_calculate_curr_xfer_param(tqspi, t);
 	tegra_qspi_start_cpu_based_transfer(tqspi, t);
 exit:
 	tqspi->curr_xfer = NULL;
 	spin_unlock_irqrestore(&tqspi->lock, flags);
 	return IRQ_HANDLED;
 }

 static irqreturn_t handle_dma_based_xfer(struct tegra_qspi *tqspi)
 {
 	struct spi_transfer *t;
 	unsigned int total_fifo_words;
 	unsigned long flags;
 	long wait_status;
 	int num_errors = 0;

 	if (tqspi->cur_direction & DATA_DIR_TX) {
 		if (tqspi->tx_status) {
 			if (tqspi->tx_dma_chan)
 				dmaengine_terminate_all(tqspi->tx_dma_chan);
 			num_errors++;
 		} else if (tqspi->tx_dma_chan) {
 			wait_status = wait_for_completion_interruptible_timeout(
 				&tqspi->tx_dma_complete, QSPI_DMA_TIMEOUT);
 			if (wait_status <= 0) {
 				dmaengine_terminate_all(tqspi->tx_dma_chan);
 				dev_err(tqspi->dev, "failed TX DMA transfer\n");
 				num_errors++;
 			}
 		}
 	}

 	if (tqspi->cur_direction & DATA_DIR_RX) {
 		if (tqspi->rx_status) {
 			if (tqspi->rx_dma_chan)
 				dmaengine_terminate_all(tqspi->rx_dma_chan);
 			num_errors++;
 		} else if (tqspi->rx_dma_chan) {
 			wait_status = wait_for_completion_interruptible_timeout(
 				&tqspi->rx_dma_complete, QSPI_DMA_TIMEOUT);
 			if (wait_status <= 0) {
 				dmaengine_terminate_all(tqspi->rx_dma_chan);
 				dev_err(tqspi->dev, "failed RX DMA transfer\n");
 				num_errors++;
 			}
 		}
 	}

 	spin_lock_irqsave(&tqspi->lock, flags);
 	t = tqspi->curr_xfer;

+	if (!t) {
+		spin_unlock_irqrestore(&tqspi->lock, flags);
+		return IRQ_HANDLED;
+	}
+
 	if (num_errors) {
 		tegra_qspi_dma_unmap_xfer(tqspi, t);
 		tegra_qspi_handle_error(tqspi);
 		complete(&tqspi->xfer_completion);
 		goto exit;
 	}

 	if (tqspi->cur_direction & DATA_DIR_RX)
 		tegra_qspi_copy_qspi_rxbuf_to_client_rxbuf(tqspi, t);

 	if (tqspi->cur_direction & DATA_DIR_TX)
 		tqspi->cur_pos = tqspi->cur_tx_pos;
 	else
 		tqspi->cur_pos = tqspi->cur_rx_pos;

 	if (tqspi->cur_pos == t->len) {
 		tegra_qspi_dma_unmap_xfer(tqspi, t);
 		complete(&tqspi->xfer_completion);
 		goto exit;
 	}

 	tegra_qspi_dma_unmap_xfer(tqspi, t);

 	/* continue transfer in current message */
 	total_fifo_words = tegra_qspi_calculate_curr_xfer_param(tqspi, t);
 	if (total_fifo_words > QSPI_FIFO_DEPTH)
 		num_errors = tegra_qspi_start_dma_based_transfer(tqspi, t);
 	else
 		num_errors = tegra_qspi_start_cpu_based_transfer(tqspi, t);

 exit:
 	spin_unlock_irqrestore(&tqspi->lock, flags);
 	return IRQ_HANDLED;
 }

 static irqreturn_t tegra_qspi_isr_thread(int irq, void *context_data)
 {
 	struct tegra_qspi *tqspi = context_data;
+	unsigned long flags;
 	u32 status;

 	/*
 	 * Read transfer status to check if interrupt was triggered by transfer
 	 * completion
 	 */
 	status = tegra_qspi_readl(tqspi, QSPI_TRANS_STATUS);

 	/*
 	 * Occasionally the IRQ thread takes a long time to wake up (usually
 	 * when the CPU that it's running on is excessively busy) and we have
 	 * already reached the timeout before and cleaned up the timed out
 	 * transfer. Avoid any processing in that case and bail out early.
 	 *
 	 * If no transfer is in progress, check if this was a real interrupt
 	 * that the timeout handler already processed, or a spurious one.
 	 */
+	spin_lock_irqsave(&tqspi->lock, flags);
 	if (!tqspi->curr_xfer) {
+		spin_unlock_irqrestore(&tqspi->lock, flags);
 		/* Spurious interrupt - transfer not ready */
 		if (!(status & QSPI_RDY))
 			return IRQ_NONE;
 		/* Real interrupt, already handled by timeout path */
 		return IRQ_HANDLED;
 	}

 	tqspi->status_reg = tegra_qspi_readl(tqspi, QSPI_FIFO_STATUS);

 	if (tqspi->cur_direction & DATA_DIR_TX)
 		tqspi->tx_status = tqspi->status_reg & (QSPI_TX_FIFO_UNF | QSPI_TX_FIFO_OVF);

 	if (tqspi->cur_direction & DATA_DIR_RX)
 		tqspi->rx_status = tqspi->status_reg & (QSPI_RX_FIFO_OVF | QSPI_RX_FIFO_UNF);

 	tegra_qspi_mask_clear_irq(tqspi);
+	spin_unlock_irqrestore(&tqspi->lock, flags);

+	/*
+	 * Lock is released here but handlers safely re-check curr_xfer under
+	 * lock before dereferencing.
+	 * DMA handler also needs to sleep in wait_for_completion_*(), which
+	 * cannot be done while holding spinlock.
+	 */
 	if (!tqspi->is_curr_dma_xfer)
 		return handle_cpu_based_xfer(tqspi);

 	return handle_dma_based_xfer(tqspi);
 }



